using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int MaxRatePoints = 10;

    public int For(int subtotalCents, LoyaltyTier loyaltyTier)
    {
        var baseRate = loyaltyTier switch
        {
            LoyaltyTier.Green => 5,
            LoyaltyTier.Gold => 7,
            LoyaltyTier.Platinum => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier)),
        };

        var bonus = subtotalCents >= 20_000 ? 3 : subtotalCents >= 5_000 ? 1 : 0;
        var rate = Math.Min(baseRate + bonus, MaxRatePoints);
        var discountCents = (int)((long)subtotalCents * rate / 100);

        return subtotalCents - discountCents;
    }
}
