using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 5% of 4999 = 249.95 -> 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // 50.00 starts the +1 band
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Gold, 19_999, 18_600)]   // 8% = 1599.92 -> 1599
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 200.00 starts the +3 band
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10% cap reached
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]  // 9+1 = 10
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // 12 capped to 10
    [InlineData(LoyaltyTier.Platinum, 0, 0)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var payable = new CalculatePayableTotal().For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, payable);
    }
}
E
